class Solution {
    public String smallestEquivalentString(String s1, String s2, String baseStr) {

        UFDS dsu = new UFDS(26);
        for(int i = 0; i < s1.length(); i++)
            dsu.union(s1.charAt(i)-97,s2.charAt(i)-97);

        StringBuilder sb = new StringBuilder(); 

        for(int i = 0; i < baseStr.length(); i++) {
            int root = dsu.root(baseStr.charAt(i) - 97);
            sb.append((char)(dsu.min[root] + 97));
        }

        return sb.toString();
    }

    class UFDS{

        int[] id;
        int[] size;
        int[] min;

        public UFDS(int N){

            id = new int[N];
            size = new int[N];
            min = new int[N];
            for(int i = 0; i < N; i++){
                id[i] = i;
                size[i] = 1;
                min[i] = i;
            }
        }

        private int root(int i){
            while (i != id[i]){
                id[i] = id[id[i]];
                i = id[i];
            }
            return i;
        }

        public void union(int i, int j){
            int rootI = root(i);
            int rootJ = root(j);
            if(rootI != rootJ){
                if(size[rootI] < size[rootJ]){
                    id[rootI] = rootJ;
                    min[rootJ] = Math.min(min[rootJ], min[rootI]);
                } else {
                    id[rootJ] = rootI;
                    min[rootI] = Math.min(min[rootI], min[rootJ]);
                }
            }
        }
    }
}
